import Foundation

/// Rules for what is recorded from the clipboard, free of AppKit so they can be tested.
public enum CapturePolicy {
    /// Markers (nspasteboard.org and older tools) that password managers and helpers set
    /// for content that must not end up in a history.
    public static let skippedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
        "net.antelle.keeweb",
    ]

    /// Whether a clipboard change may be recorded at all. `frontmostApp` is the bundle ID of the
    /// app in front when the change was seen; it is not necessarily the app that wrote it.
    public static func shouldRecord(pasteboardTypes: [String], frontmostApp: String?, config: Config) -> Bool {
        if pasteboardTypes.contains(where: skippedTypes.contains) { return false }
        if let frontmostApp, config.ignoredApps.contains(frontmostApp) { return false }
        return true
    }

    /// Plain text worth keeping: not blank and not above the size limit.
    public static func acceptsText(_ text: String) -> Bool {
        text.utf8.count <= CaptureLimits.maxTextBytes && !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    public static func acceptsRichText(byteCount: Int) -> Bool {
        byteCount <= CaptureLimits.maxRichTextBytes
    }
}
